scripts.张琳心对话.txt:
// 在碧霞岛山洞里与张琳心的对话

	If ($Event == 160) @Event160;
	Return;
@Event160:
	Say("张琳心：声音好象是从东北角传来的，我们过去看看吧。", 24);
	Return;

scripts.采花贼死亡.txt:
// 采花贼死亡

	FadeOut();
	DelNpc("采花贼");
	SaveNpc();
	StopMusic();
	Say("采花贼：小子，算你运气好，老子今天肚子有点不舒服，下次碰上给我小心点！", 202);
	PlayMusic("情缘音乐.mp3");
	ClearBody();
	Assign($Event, 150);   
	SetMapTrap(1, "trap01.txt");
	SetMapTrap(2, "trap02.txt");
	SetNpcActionFile("独孤剑", 0, "mpc007_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc007_2.asf");
	SetPlayerPos(7, 24);
	SetPlayerDir(4);
	ClearEffect();
	FadeIn();
	Sleep(1000);
	Say("独孤剑：张姑娘！张姑娘！", 6);
	Sleep(500);
	Say("独孤剑：她受了伤昏迷不醒，还是尽快回临安比较好，赶紧去找老王吧！", 6);
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	NpcSpecialAction("独孤剑", "mpc007_3.asf");
	Sleep(1000);
	Memo("碧霞岛上有无数的蒙面杀手，独孤剑勇创虎穴，在山洞中找到了绿衣女孩和采花贼，一场苦战，独孤剑击退了采花贼。");
	Memo("绿衣女孩受伤昏迷，独孤剑决定先去找老王。");
	Return;

traps.Trap03.txt:
//发现秘道的过场

	If ($Event == 160) @Event160;
	Return;	

@Event160:
	Say("独孤剑:奇怪。声音是从哪里传来的呢？", 8);
	Sleep(2000);
	Say("张琳心：咦……", 21);
	NpcGoto(张琳心, *, *);
	Sleep(1000);
	Say("张琳心：公子快看，这里有条密道！", 21);
	SetMapTrap(03, "");
	Return;

traps.trap01.txt:
// 切换到map037碧霞岛

	If ($Event == 130) @Event130;
	If ($Event == 140) @Event140;
	If ($Event == 150) @Event150;
	If ($Event == 160) @Event160;	

	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map037_碧霞岛.map");
	LoadNpc("map037.npc");
	LoadObj("map037.obj");
	SetPlayerPos(28, 12);
	SetPlayerDir(0);
	FadeIn();
	Return;

@Event130:
	Say("独孤剑：咦？洞里好像有人说话，进去看看。", 1);
	Return;

@Event140:
	Say("独孤剑：大丈夫岂能临阵脱逃？", 1);
	Return;
	
@Event150:
	FadeOut();
	SaveNpc();
	SaveObj();
	ChangeMapColor(128, 150, 200);
	ChangeAsfColor(128, 150, 200);
	LoadMap("map037_碧霞岛.map");
	LoadNpc("map037.npc");
	LoadObj("map037.obj");
	SetPlayerPos(28, 12);
	SetPlayerDir(0);
	FadeIn();
	Return;

@Event160:
	Say("张琳心：独孤公子，我们先去营救被抓的姑娘吧。", 24);
	Return;

traps.trap02.txt:
// 切换到碧霞岛秘道

	If ($Event << 160) @Eventless160;
	If ($Event == 160) @Event160;

	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map039_碧霞岛山洞秘道.map");
	LoadNpc("map039.npc");
	SaveNpc("temp_map039.npc");  //有反复战斗
	LoadObj("map039.obj");
	SetPlayerPos(9, 52);
	SetPlayerDir(4);
	FadeIn();
	Return;

@Eventless160:
	Return;
	
@Event160:
	Say("独孤剑：咦？声音好像是从这里面传出来的。", 1);	
	Say("张琳心：我们进去看看吧！", 21);
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map039_碧霞岛山洞秘道.map");
	LoadNpc("map039.npc");
	SaveNpc("temp_map039.npc");  //有反复战斗
	LoadObj("map039.obj");
	SetPlayerPos(9, 52);
	SetPlayerDir(4);
	SetNpcPos("张琳心", 8, 53);
	SetNpcDir("张琳心", 4);
	FadeIn();
	Say("独孤剑：原来这里面还有一条秘道！", 1);
	Say("张琳心：这里面黑漆漆的，不知有什么古怪，咱们要小心点。", 21);
	Say("独孤剑：嗯，你刚受了伤，如果遇到什么敌人，让我来应付好了。", 1);
	Say("张琳心：……", 21);
	SetNpcScript("张琳心", "");
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	SetNpcDeathScript("张琳心", "主角死亡.txt");
	Return;

traps.trap04.txt:
//帮助张琳心打败采花贼
	
	If ($Event == 130) @Event130;
	Return;
	
@Event130:
	LoadNpc("map038_event130.npc");
	MoveScreen(4, 100, 3);
	MoveScreen(2, 20, 3);
	Say("绿衣女孩：哼，光天化日之下你们竟敢强抢民女，让本姑娘遇上，算你们倒霉！接招！", 27);
	SetNpcMagicFile("张琳心","magic017_满城花雨.ini");
	NpcAttack("张琳心", 7, 25); 
	Sleep(1500);
	
	Say("采花贼：张姑娘不愧是“仙剑客”张风的女儿，这一招“满城花雨”果然不同凡响。", 202);
	Say("绿衣女孩：你们到处掳掠良家女子，究竟想干什么？", 27);
	Say("采花贼：我不会为难你和那些姑娘的，只要从你父亲那里把那件东西拿到手，我自然会放了你们。", 202);
	Say("绿衣女孩：你要从我父亲那里拿什么东西？为何不直接找我父亲——恐怕是没有这个胆吧？快把抓来的女子都放了，否则休怪本姑娘剑下无情！", 27);
	Say("采花贼：哈哈！是吗？张小姐，我真是挺佩服你的胆量，居然敢自投罗网让我把你带到这来。嘿嘿，劝你放下兵器投降，我还可以饶你不死，怎么样？", 202);
	Say("绿衣女孩：休想！看招！", 27);
	
	SetNpcMagicFile("张琳心","magic017_满城花雨.ini");
	PlaySound("主_女攻.wav");
	NpcAttack("张琳心", 7, 25); 
	Sleep(1500);
	SetNpcMagicFile("采花贼","magic046_投石惊浪.ini");
	NpcAttack("采花贼", 6, 23);
	Sleep(1500);
	
	PlaySound("战_女伤05.wav");
	SetNpcActionFile("张琳心", 0, "npc004_body.asf");
	SetNpcActionFile("张琳心", 1, "npc004_body.asf");
	NpcSpecialAction("张琳心", "npc004_die.asf");
	Sleep(1800);
	DelNpc("张琳心");
	AddNpc("npc004_张琳心倒地.ini", 6, 22, 7);
	SaveNpc();
	Sleep(500);
	
	Say("采花贼：可惜一个娇滴滴的女子却要舞剑弄枪，不如让本大爷来教你干点女人应该干的事情。嘿嘿……", 202);
	NpcGoto("采花贼", 7, 24);
	Say("独孤剑：住手！", 5);
	
	SetPlayerScn();
	PlayerRunTo(7, 25);
	SetPlayerDir(3);
	SetNpcDir("采花贼", 7);
	Say("采花贼：哪来的野小子，敢破坏大爷的好事。找死！", 202);
	
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("采花贼", 1);
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	Assign($Event, 140);
	SetMapTrap(4, "");
	SetMapTrap(1, "trap01.txt");
	SetMapTrap(2, "trap02.txt");
	Return;
